DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT109-S1-Q7$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT109-S1-Q7'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT109-S1-Q7$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Statements$batch07$, $batch07$Most workers don't have every item they produce checked for quality. Every piece a freelance writer writes is evaluated. That is why freelance writers produce such high-quality work.$batch07$), (1, $batch07$Evaluate$batch07$, $batch07$"That is why" is a causal claim: being evaluated on every piece causes freelance writers' high quality. Freelance writers are workers. So for at least some workers, having all their work evaluated causes high-quality work.$batch07$), (2, $batch07$Goal$batch07$, $batch07$Evaluating every piece causes high-quality work, at least for some workers.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT109-S1-Q7$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$This is the most popular wrong answer. The passage is about *how many* pieces get checked, not *how strictly*. Freelance writers have every piece evaluated; most workers don't. Nothing says a freelance piece gets a tougher review than any one item another worker makes.$batch07$), ($batch07$B$batch07$, $batch07$Freelance writers are "some workers", and the consultant says evaluating every piece is why their work is high quality.$batch07$), ($batch07$C$batch07$, $batch07$The passage says freelance writers do high-quality work, not that nobody does better.$batch07$), ($batch07$D$batch07$, $batch07$"Most workers" don't have every item evaluated. That leaves room for some other workers who do.$batch07$), ($batch07$E$batch07$, $batch07$The passage never says anyone does high-quality work *without* full evaluation.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT109-S1-Q7$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
